  "source": "def investigate(context, acquire):
    committed = {}
    main_tx = None
    other_tx = None
    main_changes = 0
    other_changes = 0
    actions = context["actions"]
    for action in actions:
        op = action["op"]
        conn = action.get("connection", "main")
        blocked = False
        if conn == "main" and other_tx is not None:
            blocked = True
        if conn == "other" and main_tx is not None:
            blocked = True
        if not blocked:
            if op == "begin":
                if conn == "main":
                    if main_tx is None:
                        main_tx = dict(committed)
                else:
                    if other_tx is None:
                        other_tx = dict(committed)
            elif op == "commit":
                if conn == "main":
                    if main_tx is not None:
                        committed = main_tx
                        main_tx = None
                else:
                    if other_tx is not None:
                        committed = other_tx
                        other_tx = None
            elif op == "rollback":
                if conn == "main":
                    main_tx = None
                else:
                    other_tx = None
            elif op == "put":
                key = action["key"]
                value = action["value"]
                if conn == "main":
                    state = main_tx if main_tx is not None else committed
                    if key not in state:
                        state[key] = value
                        main_changes += 1
                else:
                    state = other_tx if other_tx is not None else committed
                    if key not in state:
                        state[key] = value
                        other_changes += 1
            elif op == "update":
                key = action["key"]
                value = action["value"]
                if conn == "main":
                    state = main_tx if main_tx is not None else committed
                    if key in state:
                        state[key] = value
                        main_changes += 1
                else:
                    state = other_tx if other_tx is not None else committed
                    if key in state:
                        state[key] = value
                        other_changes += 1
            elif op == "delete":
                key = action["key"]
                if conn == "main":
                    state = main_tx if main_tx is not None else committed
                    if key in state:
                        state.pop(key)
                        main_changes += 1
                else:
                    state = other_tx if other_tx is not None else committed
                    if key in state:
                        state.pop(key)
                        other_changes += 1
    goal = context["goal"]
    if goal == "channel":
        value = main_changes + other_changes
    elif goal == "committed_count":
        value = len(committed)
    elif goal == "committed_sum":
        value = sum(committed.values())
    else:
        return {"value": None, "unresolved": True}
    return {"value": value, "unresolved": False}
",
  "scope": "SQLite INSERT OR IGNORE semantics with total_changes summed across both connections; transactions isolate pending changes until commit, and an open transaction blocks writes and transaction actions on the other connection.",
  "lesson": "Channel equals sum of successful writes on main and other connections; committed state reflects only committed transactions; other connection is blocked while a transaction is open."
